#include "2mm.h"

extern "C" {

void kernel_2mm(   
		double alpha,
		double beta,
		double tmp[ NI + 0][NJ + 0],
		double A[ NI + 0][NK + 0],
		double B[ NK + 0][NJ + 0],
		double C[ NJ + 0][NL + 0],
		double D[ NI + 0][NL + 0])
{
#pragma HLS INTERFACE m_axi port=tmp    offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A      offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B      offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=C      offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=D      offset=slave bundle=gmem4
#pragma HLS INTERFACE s_axilite port=alpha  bundle=control
#pragma HLS INTERFACE s_axilite port=beta   bundle=control
#pragma HLS INTERFACE s_axilite port=tmp    bundle=control
#pragma HLS INTERFACE s_axilite port=A      bundle=control
#pragma HLS INTERFACE s_axilite port=B      bundle=control
#pragma HLS INTERFACE s_axilite port=C      bundle=control
#pragma HLS INTERFACE s_axilite port=D      bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local buffers for all matrices to enable partitioning and fast access
    double l_tmp[NI][NJ];
    double l_A[NI][NK];
    double l_B[NK][NJ];
    double l_C[NJ][NL];
    double l_D[NI][NL];

#pragma HLS ARRAY_PARTITION variable=l_tmp cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=l_A   cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=l_B   cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=l_C   cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=l_D   cyclic factor=8 dim=2

    // Load A
    load_A_i: for (int i = 0; i < NI; i++) {
        load_A_k: for (int k = 0; k < NK; k++) {
#pragma HLS PIPELINE II=1
            l_A[i][k] = A[i][k];
        }
    }

    // Load B
    load_B_k: for (int k = 0; k < NK; k++) {
        load_B_j: for (int j = 0; j < NJ; j++) {
#pragma HLS PIPELINE II=1
            l_B[k][j] = B[k][j];
        }
    }

    // Load C
    load_C_j: for (int j = 0; j < NJ; j++) {
        load_C_l: for (int l = 0; l < NL; l++) {
#pragma HLS PIPELINE II=1
            l_C[j][l] = C[j][l];
        }
    }

    // Load D
    load_D_i: for (int i = 0; i < NI; i++) {
        load_D_l: for (int l = 0; l < NL; l++) {
#pragma HLS PIPELINE II=1
            l_D[i][l] = D[i][l];
        }
    }

    // First matrix multiply: tmp = alpha * A * B
    mm1_i: for (int i = 0; i < NI; i++) {
        mm1_j: for (int j = 0; j < NJ; j++) {
#pragma HLS PIPELINE II=1
            double acc = 0.0;
            mm1_k: for (int k = 0; k < NK; k++) {
#pragma HLS UNROLL factor=8
                acc += alpha * l_A[i][k] * l_B[k][j];
            }
            l_tmp[i][j] = acc;
        }
    }

    // Second matrix multiply: D = beta * D + tmp * C
    mm2_i: for (int i = 0; i < NI; i++) {
        mm2_j: for (int j = 0; j < NL; j++) {
#pragma HLS PIPELINE II=1
            double acc = beta * l_D[i][j];
            mm2_k: for (int k = 0; k < NJ; k++) {
#pragma HLS UNROLL factor=8
                acc += l_tmp[i][k] * l_C[k][j];
            }
            l_D[i][j] = acc;
        }
    }

    // Write back tmp
    store_tmp_i: for (int i = 0; i < NI; i++) {
        store_tmp_j: for (int j = 0; j < NJ; j++) {
#pragma HLS PIPELINE II=1
            tmp[i][j] = l_tmp[i][j];
        }
    }

    // Write back D
    store_D_i: for (int i = 0; i < NI; i++) {
        store_D_l: for (int l = 0; l < NL; l++) {
#pragma HLS PIPELINE II=1
            D[i][l] = l_D[i][l];
        }
    }
}

} // extern "C"

#include "3mm.h"

extern "C" {

void kernel_3mm(    
		double E[ NI + 0][NJ + 0],
		double A[ NI + 0][NK + 0],
		double B[ NK + 0][NJ + 0],
		double F[ NJ + 0][NL + 0],
		double C[ NJ + 0][NM + 0],
		double D[ NM + 0][NL + 0],
		double G[ NI + 0][NL + 0])
{
#pragma HLS INTERFACE m_axi port=E offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=F offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem4
#pragma HLS INTERFACE m_axi port=D offset=slave bundle=gmem5
#pragma HLS INTERFACE m_axi port=G offset=slave bundle=gmem6
#pragma HLS INTERFACE s_axilite port=E bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=F bundle=control
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=D bundle=control
#pragma HLS INTERFACE s_axilite port=G bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local buffers for tiling/reuse
    double localA[NI][NK];
    double localB[NK][NJ];
    double localC[NJ][NM];
    double localD[NM][NL];
    double localE[NI][NJ];
    double localF[NJ][NL];
    double localG[NI][NL];

#pragma HLS ARRAY_PARTITION variable=localA cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=localB cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=localC cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=localD cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=localE cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=localF cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=localG cyclic factor=8 dim=2

    // Load A
    load_A: for (int i = 0; i < NI; i++)
        for (int k = 0; k < NK; k++) {
#pragma HLS PIPELINE II=1
            localA[i][k] = A[i][k];
        }

    // Load B
    load_B: for (int k = 0; k < NK; k++)
        for (int j = 0; j < NJ; j++) {
#pragma HLS PIPELINE II=1
            localB[k][j] = B[k][j];
        }

    // Compute E = A * B
    comp_E_i: for (int i = 0; i < NI; i++) {
        comp_E_j: for (int j = 0; j < NJ; j++) {
#pragma HLS PIPELINE II=1
            double sum = 0.0;
            comp_E_k: for (int k = 0; k < NK; ++k) {
#pragma HLS UNROLL factor=8
                sum += localA[i][k] * localB[k][j];
            }
            localE[i][j] = sum;
        }
    }

    // Load C
    load_C: for (int i = 0; i < NJ; i++)
        for (int k = 0; k < NM; k++) {
#pragma HLS PIPELINE II=1
            localC[i][k] = C[i][k];
        }

    // Load D
    load_D: for (int k = 0; k < NM; k++)
        for (int j = 0; j < NL; j++) {
#pragma HLS PIPELINE II=1
            localD[k][j] = D[k][j];
        }

    // Compute F = C * D
    comp_F_i: for (int i = 0; i < NJ; i++) {
        comp_F_j: for (int j = 0; j < NL; j++) {
#pragma HLS PIPELINE II=1
            double sum = 0.0;
            comp_F_k: for (int k = 0; k < NM; ++k) {
#pragma HLS UNROLL factor=8
                sum += localC[i][k] * localD[k][j];
            }
            localF[i][j] = sum;
        }
    }

    // Compute G = E * F
    comp_G_i: for (int i = 0; i < NI; i++) {
        comp_G_j: for (int j = 0; j < NL; j++) {
#pragma HLS PIPELINE II=1
            double sum = 0.0;
            comp_G_k: for (int k = 0; k < NJ; ++k) {
#pragma HLS UNROLL factor=8
                sum += localE[i][k] * localF[k][j];
            }
            localG[i][j] = sum;
        }
    }

    // Write back E
    store_E: for (int i = 0; i < NI; i++)
        for (int j = 0; j < NJ; j++) {
#pragma HLS PIPELINE II=1
            E[i][j] = localE[i][j];
        }

    // Write back F
    store_F: for (int i = 0; i < NJ; i++)
        for (int j = 0; j < NL; j++) {
#pragma HLS PIPELINE II=1
            F[i][j] = localF[i][j];
        }

    // Write back G
    store_G: for (int i = 0; i < NI; i++)
        for (int j = 0; j < NL; j++) {
#pragma HLS PIPELINE II=1
            G[i][j] = localG[i][j];
        }
}

} // extern "C"

#include "atax.h"

extern "C" {

void kernel_atax( 
		 double A[ M + 0][N + 0],
		 double x[ N + 0],
		 double y[ N + 0],
		 double tmp[ M + 0])
{
#pragma HLS INTERFACE m_axi port=A   offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=x   offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=y   offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=tmp offset=slave bundle=gmem3
#pragma HLS INTERFACE s_axilite port=A   bundle=control
#pragma HLS INTERFACE s_axilite port=x   bundle=control
#pragma HLS INTERFACE s_axilite port=y   bundle=control
#pragma HLS INTERFACE s_axilite port=tmp bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local buffers to stage global memory reads for reuse
    double local_x[N];
    double local_y[N];
    double local_tmp[M];
    double local_A[M][N];

#pragma HLS ARRAY_PARTITION variable=local_x   cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=local_y   cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=local_tmp cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=local_A   cyclic factor=8 dim=2

    const int m = M;
    const int n = N;

    // Load x from global memory
    load_x: for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
        local_x[j] = x[j];
    }

    // Load A from global memory
    load_A: for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            local_A[i][j] = A[i][j];
        }
    }

    // Initialize y to 0
    init_y: for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        local_y[i] = 0.0;
    }

    // Main computation
    for (int i = 0; i < m; i++) {
        local_tmp[i] = 0.0;

        // Compute tmp[i] = sum_j A[i][j] * x[j]
        dot1: for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            local_tmp[i] = local_tmp[i] + local_A[i][j] * local_x[j];
        }

        // Accumulate y[j] += A[i][j] * tmp[i]
        dot2: for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            local_y[j] = local_y[j] + local_A[i][j] * local_tmp[i];
        }
    }

    // Write results back to global memory
    store_y: for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
        y[j] = local_y[j];
    }

    store_tmp: for (int i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
        tmp[i] = local_tmp[i];
    }
}

} // extern "C"

#include "bicg.h"

extern "C" {

void kernel_bicg( 
         double A[ N + 0][M + 0],
         double s[ M + 0],
         double q[ N + 0],
         double p[ M + 0],
         double r[ N + 0])
{
    #pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
    #pragma HLS INTERFACE m_axi port=s offset=slave bundle=gmem1
    #pragma HLS INTERFACE m_axi port=q offset=slave bundle=gmem2
    #pragma HLS INTERFACE m_axi port=p offset=slave bundle=gmem3
    #pragma HLS INTERFACE m_axi port=r offset=slave bundle=gmem4
    #pragma HLS INTERFACE s_axilite port=A bundle=control
    #pragma HLS INTERFACE s_axilite port=s bundle=control
    #pragma HLS INTERFACE s_axilite port=q bundle=control
    #pragma HLS INTERFACE s_axilite port=p bundle=control
    #pragma HLS INTERFACE s_axilite port=r bundle=control
    #pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local buffers for arrays accessed repeatedly in the loop nest
    double local_s[M];
    double local_q[N];
    double local_p[M];
    double local_r[N];
    double local_A[N][M];

    #pragma HLS ARRAY_PARTITION variable=local_s  cyclic factor=8 dim=1
    #pragma HLS ARRAY_PARTITION variable=local_q  cyclic factor=8 dim=1
    #pragma HLS ARRAY_PARTITION variable=local_p  cyclic factor=8 dim=1
    #pragma HLS ARRAY_PARTITION variable=local_r  cyclic factor=8 dim=1
    #pragma HLS ARRAY_PARTITION variable=local_A  cyclic factor=8 dim=2

    // Load inputs into local buffers
    load_r: for (int i = 0; i < N; i++) {
        #pragma HLS PIPELINE II=1
        local_r[i] = r[i];
    }
    load_p: for (int j = 0; j < M; j++) {
        #pragma HLS PIPELINE II=1
        local_p[j] = p[j];
    }
    load_A: for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            #pragma HLS PIPELINE II=1
            local_A[i][j] = A[i][j];
        }
    }

    // Initialize s
    init_s: for (int i = 0; i < M; i++) {
        #pragma HLS PIPELINE II=1
        local_s[i] = 0.0;
    }

    // Main computation
    outer_loop: for (int i = 0; i < N; i++) {
        double q_i = 0.0;
        inner_loop: for (int j = 0; j < M; j++) {
            #pragma HLS PIPELINE II=1
            double a_ij = local_A[i][j];
            local_s[j] = local_s[j] + local_r[i] * a_ij;
            q_i = q_i + a_ij * local_p[j];
        }
        local_q[i] = q_i;
    }

    // Store outputs
    store_s: for (int j = 0; j < M; j++) {
        #pragma HLS PIPELINE II=1
        s[j] = local_s[j];
    }
    store_q: for (int i = 0; i < N; i++) {
        #pragma HLS PIPELINE II=1
        q[i] = local_q[i];
    }
}

} // extern "C"

#include "cholesky.h"

extern "C" {

void kernel_cholesky(
        double A[N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem depth=14400
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local buffer for the working matrix to avoid repeated global memory accesses
    double L[N][N];
#pragma HLS ARRAY_PARTITION variable=L cyclic factor=8 dim=2

    // Load A into local buffer
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            L[i][j] = A[i][j];
        }
    }

    const int n = N;
    int i, j, k;

    for (i = 0; i < n; i++) {

        for (j = 0; j < i; j++) {
            double sum_ij = L[i][j];
            for (k = 0; k < j; k++) {
#pragma HLS PIPELINE II=1
#pragma HLS DEPENDENCE variable=L inter false
                sum_ij -= L[i][k] * L[j][k];
            }
            L[i][j] = sum_ij / L[j][j];
        }

        double sum_ii = L[i][i];
        for (k = 0; k < i; k++) {
#pragma HLS PIPELINE II=1
            sum_ii -= L[i][k] * L[i][k];
        }
        L[i][i] = sqrt(sum_ii);
    }

    // Store result back to global memory
    for (int ii = 0; ii < N; ii++) {
        for (int jj = 0; jj < N; jj++) {
#pragma HLS PIPELINE II=1
            A[ii][jj] = L[ii][jj];
        }
    }
}

} // extern "C"

#include "correlation.h"

extern "C" {

void kernel_correlation(
            double float_n,
            double data[ N + 0][M + 0],
            double corr[ M + 0][M + 0],
            double mean[ M + 0],
            double stddev[ M + 0])
{
#pragma HLS INTERFACE m_axi port=data   offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=corr   offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=mean   offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=stddev offset=slave bundle=gmem3
#pragma HLS INTERFACE s_axilite port=float_n bundle=control
#pragma HLS INTERFACE s_axilite port=data    bundle=control
#pragma HLS INTERFACE s_axilite port=corr    bundle=control
#pragma HLS INTERFACE s_axilite port=mean    bundle=control
#pragma HLS INTERFACE s_axilite port=stddev  bundle=control
#pragma HLS INTERFACE s_axilite port=return  bundle=control

    // Local copies of data, mean, stddev, corr for efficient access
    double l_data[N][M];
    double l_mean[M];
    double l_stddev[M];
    double l_corr[M][M];

#pragma HLS ARRAY_PARTITION variable=l_data   cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=l_mean   cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_stddev cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_corr   cyclic factor=8 dim=2

    const int n = N;
    const int m = M;
    int i, j, k;
    double eps = 0.1;

    // Load data from global memory
    load_data_i: for (i = 0; i < n; i++) {
        load_data_j: for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
            l_data[i][j] = data[i][j];
        }
    }

    // Compute mean
    mean_j: for (j = 0; j < m; j++) {
        double mean_val = 0.0;
        mean_i: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
            mean_val += l_data[i][j];
        }
        l_mean[j] = mean_val / float_n;
    }

    // Compute stddev
    stddev_j: for (j = 0; j < m; j++) {
        double stddev_val = 0.0;
        stddev_i: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
            double diff = l_data[i][j] - l_mean[j];
            stddev_val += diff * diff;
        }
        stddev_val /= float_n;
        stddev_val = sqrt(stddev_val);
        l_stddev[j] = stddev_val <= eps ? 1.0 : stddev_val;
    }

    // Store mean and stddev to global memory
    store_mean_j: for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
        mean[j]   = l_mean[j];
        stddev[j] = l_stddev[j];
    }

    // Normalize data
    double sqrt_float_n = sqrt(float_n);
    norm_i: for (i = 0; i < n; i++) {
        norm_j: for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
            l_data[i][j] -= l_mean[j];
            l_data[i][j] /= sqrt_float_n * l_stddev[j];
        }
    }

    // Compute correlation matrix
    corr_i: for (i = 0; i < m - 1; i++) {
        l_corr[i][i] = 1.0;
        corr_j: for (j = i + 1; j < m; j++) {
            double corr_val = 0.0;
            corr_k: for (k = 0; k < n; k++) {
#pragma HLS PIPELINE II=1
                corr_val += l_data[k][i] * l_data[k][j];
            }
            l_corr[i][j] = corr_val;
            l_corr[j][i] = corr_val;
        }
    }
    l_corr[m-1][m-1] = 1.0;

    // Write back normalized data to global memory
    store_data_i: for (i = 0; i < n; i++) {
        store_data_j: for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
            data[i][j] = l_data[i][j];
        }
    }

    // Write back corr to global memory
    store_corr_i: for (i = 0; i < m; i++) {
        store_corr_j: for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
            corr[i][j] = l_corr[i][j];
        }
    }
}

} // extern "C"

#include "covariance.h"

extern "C" {

void kernel_covariance(
		       double float_n,
		       double data[ N + 0][M + 0],
		       double cov[ M + 0][M + 0],
		       double mean[ M + 0])
{
#pragma HLS INTERFACE m_axi port=data   offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=cov    offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=mean   offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=float_n bundle=control
#pragma HLS INTERFACE s_axilite port=data    bundle=control
#pragma HLS INTERFACE s_axilite port=cov     bundle=control
#pragma HLS INTERFACE s_axilite port=mean    bundle=control
#pragma HLS INTERFACE s_axilite port=return  bundle=control

    const int n = N;
    const int m = M;

    // Local buffers for data and mean to allow partitioning and fast access
    double local_data[N][M];
    double local_mean[M];
    double local_cov[M][M];

#pragma HLS ARRAY_PARTITION variable=local_data cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=local_mean complete dim=1
#pragma HLS ARRAY_PARTITION variable=local_cov  cyclic factor=8 dim=2

    int i, j, k;

    // Load data from global memory
    for (i = 0; i < n; i++) {
        for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
            local_data[i][j] = data[i][j];
        }
    }

    // Compute mean for each column
    for (j = 0; j < m; j++)
    {
        local_mean[j] = 0.0;
        for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
            local_mean[j] += local_data[i][j];
        }
        local_mean[j] /= float_n;
    }

    // Subtract mean from each element
    for (i = 0; i < n; i++) {
        for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
            local_data[i][j] -= local_mean[j];
        }
    }

    // Compute covariance matrix
    for (i = 0; i < m; i++) {
        for (j = i; j < m; j++) {
            double cov_ij = 0.0;
            for (k = 0; k < n; k++) {
#pragma HLS PIPELINE II=1
                cov_ij += local_data[k][i] * local_data[k][j];
            }
            cov_ij /= (float_n - 1.0);
            local_cov[i][j] = cov_ij;
            local_cov[j][i] = cov_ij;
        }
    }

    // Write mean to global memory
    for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
        mean[j] = local_mean[j];
    }

    // Write cov to global memory
    for (i = 0; i < m; i++) {
        for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
            cov[i][j] = local_cov[i][j];
        }
    }

}

} // extern "C"

#include "doitgen.h"

void kernel_doitgen(  
		    double A[ NR + 0][NQ + 0][NP + 0],
		    double C4[ NP + 0][NP + 0],
		    double sum[ NP + 0])
{
#pragma HLS INTERFACE m_axi port=A   offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=C4  offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=sum offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=A      bundle=control
#pragma HLS INTERFACE s_axilite port=C4     bundle=control
#pragma HLS INTERFACE s_axilite port=sum    bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int nr = NR;
    const int nq = NQ;
    const int np = NP;

    // Local buffers for reduced global-memory traffic
    double l_A[NQ][NP];
    double l_C4[NP][NP];
    double l_sum[NP];

#pragma HLS ARRAY_PARTITION variable=l_A   cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=l_C4  cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=l_sum cyclic factor=8 dim=1

    // Pre-load C4 once into local buffer
    load_c4_row: for (int s = 0; s < NP; s++) {
        load_c4_col: for (int p = 0; p < NP; p++) {
#pragma HLS PIPELINE II=1
            l_C4[s][p] = C4[s][p];
        }
    }

    int r, q, p, s;

    for (r = 0; r < nr; r++) {

        // Load A[r][*][*] into local buffer
        load_a_q: for (q = 0; q < nq; q++) {
            load_a_p: for (p = 0; p < np; p++) {
#pragma HLS PIPELINE II=1
                l_A[q][p] = A[r][q][p];
            }
        }

        // Compute
        for (q = 0; q < nq; q++) {

            // Initialize sum and compute dot products
            for (p = 0; p < np; p++) {
                l_sum[p] = 0.0;
                for (s = 0; s < np; s++) {
#pragma HLS PIPELINE II=1
                    l_sum[p] += l_A[q][s] * l_C4[s][p];
                }
            }

            // Write back sum into local A tile
            write_back: for (p = 0; p < np; p++) {
#pragma HLS PIPELINE II=1
                l_A[q][p] = l_sum[p];
            }
        }

        // Store result back to global A
        store_a_q: for (q = 0; q < nq; q++) {
            store_a_p: for (p = 0; p < np; p++) {
#pragma HLS PIPELINE II=1
                A[r][q][p] = l_A[q][p];
            }
        }
    }

    // Write final sum[] output (last r,q slice sum values)
    // Preserve original interface: write l_sum back to global sum
    write_sum: for (p = 0; p < np; p++) {
#pragma HLS PIPELINE II=1
        sum[p] = l_sum[p];
    }
}

#include "durbin.h"

extern "C" {
void kernel_durbin(
		   double r[ N + 0],
		   double y[ N + 0])
{
#pragma HLS INTERFACE m_axi port=r offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=y offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=r bundle=control
#pragma HLS INTERFACE s_axilite port=y bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

    double z[N];
    double r_local[N];
    double y_local[N];

#pragma HLS ARRAY_PARTITION variable=z complete dim=1
#pragma HLS ARRAY_PARTITION variable=r_local complete dim=1
#pragma HLS ARRAY_PARTITION variable=y_local complete dim=1

    double alpha;
    double beta;
    double sum;

    int i, k;

    // Load r into local buffer
    for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        r_local[i] = r[i];
    }

    y_local[0] = -r_local[0];
    beta = 1.0;
    alpha = -r_local[0];

    for (k = 1; k < n; k++) {
        beta = (1 - alpha * alpha) * beta;
        sum = 0.0;

        for (i = 0; i < k; i++) {
#pragma HLS PIPELINE II=1
            sum += r_local[k - i - 1] * y_local[i];
        }

        alpha = -(r_local[k] + sum) / beta;

        for (i = 0; i < k; i++) {
#pragma HLS PIPELINE II=1
            z[i] = y_local[i] + alpha * y_local[k - i - 1];
        }

        for (i = 0; i < k; i++) {
#pragma HLS PIPELINE II=1
            y_local[i] = z[i];
        }

        y_local[k] = alpha;
    }

    // Write y_local back to output
    for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        y[i] = y_local[i];
    }
}
}

#include "fdtd-2d.h"

extern "C" {

void kernel_fdtd_2d(
            double ex[ NX + 0][NY + 0],
            double ey[ NX + 0][NY + 0],
            double hz[ NX + 0][NY + 0],
            double _fict_[ TMAX + 0])
{
#pragma HLS INTERFACE m_axi port=ex offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=ey offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=hz offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=_fict_ offset=slave bundle=gmem3
#pragma HLS INTERFACE s_axilite port=ex bundle=control
#pragma HLS INTERFACE s_axilite port=ey bundle=control
#pragma HLS INTERFACE s_axilite port=hz bundle=control
#pragma HLS INTERFACE s_axilite port=_fict_ bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local buffers to avoid repeated global memory access
    static double l_ex[NX][NY];
    static double l_ey[NX][NY];
    static double l_hz[NX][NY];
    static double l_fict[TMAX];

#pragma HLS ARRAY_PARTITION variable=l_ex cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=l_ey cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=l_hz cyclic factor=8 dim=2

    const int tmax = TMAX;
    const int nx = NX;
    const int ny = NY;

    // Load _fict_ from global memory
    load_fict: for (int t = 0; t < tmax; t++) {
#pragma HLS PIPELINE II=1
        l_fict[t] = _fict_[t];
    }

    // Load ex from global memory
    load_ex: for (int i = 0; i < nx; i++) {
        for (int j = 0; j < ny; j++) {
#pragma HLS PIPELINE II=1
            l_ex[i][j] = ex[i][j];
        }
    }

    // Load ey from global memory
    load_ey: for (int i = 0; i < nx; i++) {
        for (int j = 0; j < ny; j++) {
#pragma HLS PIPELINE II=1
            l_ey[i][j] = ey[i][j];
        }
    }

    // Load hz from global memory
    load_hz: for (int i = 0; i < nx; i++) {
        for (int j = 0; j < ny; j++) {
#pragma HLS PIPELINE II=1
            l_hz[i][j] = hz[i][j];
        }
    }

    int t, i, j;

    for (t = 0; t < tmax; t++) {
        // Update ey[0][j] = _fict_[t]
        ey_boundary: for (j = 0; j < ny; j++) {
#pragma HLS PIPELINE II=1
            l_ey[0][j] = l_fict[t];
        }

        // Update ey[i][j] for i >= 1
        ey_update: for (i = 1; i < nx; i++) {
            for (j = 0; j < ny; j++) {
#pragma HLS PIPELINE II=1
                l_ey[i][j] = l_ey[i][j] - 0.5 * (l_hz[i][j] - l_hz[i-1][j]);
            }
        }

        // Update ex[i][j] for j >= 1
        ex_update: for (i = 0; i < nx; i++) {
            for (j = 1; j < ny; j++) {
#pragma HLS PIPELINE II=1
                l_ex[i][j] = l_ex[i][j] - 0.5 * (l_hz[i][j] - l_hz[i][j-1]);
            }
        }

        // Update hz[i][j]
        hz_update: for (i = 0; i < nx - 1; i++) {
            for (j = 0; j < ny - 1; j++) {
#pragma HLS PIPELINE II=1
                l_hz[i][j] = l_hz[i][j] - 0.7 * (l_ex[i][j+1] - l_ex[i][j] +
                                                    l_ey[i+1][j] - l_ey[i][j]);
            }
        }
    }

    // Store ex back to global memory
    store_ex: for (int i = 0; i < nx; i++) {
        for (int j = 0; j < ny; j++) {
#pragma HLS PIPELINE II=1
            ex[i][j] = l_ex[i][j];
        }
    }

    // Store ey back to global memory
    store_ey: for (int i = 0; i < nx; i++) {
        for (int j = 0; j < ny; j++) {
#pragma HLS PIPELINE II=1
            ey[i][j] = l_ey[i][j];
        }
    }

    // Store hz back to global memory
    store_hz: for (int i = 0; i < nx; i++) {
        for (int j = 0; j < ny; j++) {
#pragma HLS PIPELINE II=1
            hz[i][j] = l_hz[i][j];
        }
    }
}

} // extern "C"

#include "floyd-warshall.h"

extern "C" {

void kernel_floyd_warshall(int path[N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=path offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=path bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local copy for all computation to avoid repeated global memory accesses
    int local_path[N][N];
#pragma HLS ARRAY_PARTITION variable=local_path cyclic factor=8 dim=2

    // Load path into local buffer
    load_i: for (int i = 0; i < N; i++) {
        load_j: for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            local_path[i][j] = path[i][j];
        }
    }

    const int n = N;
    int i, j, k;

    // Floyd-Warshall: k carries true loop-carried dependency across all (i,j)
    for (k = 0; k < n; k++) {
        // Cache the k-th row: path[k][j] accessed for all i
        int row_k[N];
#pragma HLS ARRAY_PARTITION variable=row_k cyclic factor=8 dim=1
        cache_k: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            row_k[j] = local_path[k][j];
        }

        for (i = 0; i < n; i++) {
            // Cache path[i][k] as scalar for the inner j loop
            int path_ik = local_path[i][k];
            compute_j: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
                int through_k = path_ik + row_k[j];
                int cur = local_path[i][j];
                local_path[i][j] = (cur < through_k) ? cur : through_k;
            }
        }
    }

    // Store result back
    store_i: for (int i = 0; i < N; i++) {
        store_j: for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            path[i][j] = local_path[i][j];
        }
    }
}

} // extern "C"

#include "gemm.h"

extern "C" {

void kernel_gemm(
         double alpha,
         double beta,
         double C[ NI + 0][NJ + 0],
         double A[ NI + 0][NK + 0],
         double B[ NK + 0][NJ + 0])
{
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta  bundle=control
#pragma HLS INTERFACE s_axilite port=C     bundle=control
#pragma HLS INTERFACE s_axilite port=A     bundle=control
#pragma HLS INTERFACE s_axilite port=B     bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local tile buffers for data reuse
    double localA[NI][NK];
    double localB[NK][NJ];
    double localC[NI][NJ];

#pragma HLS ARRAY_PARTITION variable=localA cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=localB cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=localC cyclic factor=8 dim=2

    // Load A from global memory
    load_A_i: for (int i = 0; i < NI; i++) {
        load_A_k: for (int k = 0; k < NK; k++) {
#pragma HLS PIPELINE II=1
            localA[i][k] = A[i][k];
        }
    }

    // Load B from global memory
    load_B_k: for (int k = 0; k < NK; k++) {
        load_B_j: for (int j = 0; j < NJ; j++) {
#pragma HLS PIPELINE II=1
            localB[k][j] = B[k][j];
        }
    }

    // Load C from global memory
    load_C_i: for (int i = 0; i < NI; i++) {
        load_C_j: for (int j = 0; j < NJ; j++) {
#pragma HLS PIPELINE II=1
            localC[i][j] = C[i][j];
        }
    }

    // Compute: scale C by beta, then accumulate alpha*A*B
    int i, j, k;
    for (i = 0; i < NI; i++) {
        // Scale row of C by beta
        scale_j: for (j = 0; j < NJ; j++) {
#pragma HLS PIPELINE II=1
            localC[i][j] *= beta;
        }
        // Accumulate alpha * A[i][k] * B[k][j] into C[i][j]
        for (k = 0; k < NK; k++) {
            accum_j: for (j = 0; j < NJ; j++) {
#pragma HLS PIPELINE II=1
                localC[i][j] += alpha * localA[i][k] * localB[k][j];
            }
        }
    }

    // Store C back to global memory
    store_C_i: for (int ii = 0; ii < NI; ii++) {
        store_C_j: for (int jj = 0; jj < NJ; jj++) {
#pragma HLS PIPELINE II=1
            C[ii][jj] = localC[ii][jj];
        }
    }
}

} // extern "C"

#include "gemver.h"

extern "C" {

void kernel_gemver(
		   double alpha,
		   double beta,
		   double A[ N + 0][N + 0],
		   double u1[ N + 0],
		   double v1[ N + 0],
		   double u2[ N + 0],
		   double v2[ N + 0],
		   double w[ N + 0],
		   double x[ N + 0],
		   double y[ N + 0],
		   double z[ N + 0])
{
#pragma HLS INTERFACE m_axi port=A   offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=u1  offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=v1  offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=u2  offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=v2  offset=slave bundle=gmem4
#pragma HLS INTERFACE m_axi port=w   offset=slave bundle=gmem5
#pragma HLS INTERFACE m_axi port=x   offset=slave bundle=gmem6
#pragma HLS INTERFACE m_axi port=y   offset=slave bundle=gmem7
#pragma HLS INTERFACE m_axi port=z   offset=slave bundle=gmem8

#pragma HLS INTERFACE s_axilite port=alpha  bundle=control
#pragma HLS INTERFACE s_axilite port=beta   bundle=control
#pragma HLS INTERFACE s_axilite port=A      bundle=control
#pragma HLS INTERFACE s_axilite port=u1     bundle=control
#pragma HLS INTERFACE s_axilite port=v1     bundle=control
#pragma HLS INTERFACE s_axilite port=u2     bundle=control
#pragma HLS INTERFACE s_axilite port=v2     bundle=control
#pragma HLS INTERFACE s_axilite port=w      bundle=control
#pragma HLS INTERFACE s_axilite port=x      bundle=control
#pragma HLS INTERFACE s_axilite port=y      bundle=control
#pragma HLS INTERFACE s_axilite port=z      bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

    // Local buffers for frequently reused vectors
    double l_u1[N], l_u2[N];
    double l_v1[N], l_v2[N];
    double l_x[N],  l_y[N],  l_z[N];
    double l_w[N];
    double l_A[N][N];

#pragma HLS ARRAY_PARTITION variable=l_u1 cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_u2 cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_v1 cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_v2 cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_x  cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_y  cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_z  cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_w  cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_A  cyclic factor=8 dim=2

    // Load vectors from global memory
    load_u1: for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        l_u1[i] = u1[i];
        l_u2[i] = u2[i];
        l_v1[i] = v1[i];
        l_v2[i] = v2[i];
        l_x[i]  = x[i];
        l_y[i]  = y[i];
        l_z[i]  = z[i];
        l_w[i]  = w[i];
    }

    // Load A from global memory
    load_A: for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            l_A[i][j] = A[i][j];
        }
    }

    // Loop 1: A[i][j] += u1[i]*v1[j] + u2[i]*v2[j]
    loop1_i: for (int i = 0; i < n; i++) {
        double u1i = l_u1[i];
        double u2i = l_u2[i];
        loop1_j: for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            l_A[i][j] = l_A[i][j] + u1i * l_v1[j] + u2i * l_v2[j];
        }
    }

    // Loop 2: x[i] += beta * A[j][i] * y[j]  (column-wise access of A)
    // Rewrite as: x[i] += beta * sum_j( A[j][i] * y[j] )
    // To avoid column-access pattern, transpose mentally: iterate j-outer, i-inner
    loop2_j: for (int j = 0; j < n; j++) {
        double beta_yj = beta * l_y[j];
        loop2_i: for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
            l_x[i] = l_x[i] + beta_yj * l_A[j][i];
        }
    }

    // Loop 3: x[i] += z[i]
    loop3: for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        l_x[i] = l_x[i] + l_z[i];
    }

    // Loop 4: w[i] += alpha * A[i][j] * x[j]
    loop4_i: for (int i = 0; i < n; i++) {
        double wi = l_w[i];
        loop4_j: for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            wi = wi + alpha * l_A[i][j] * l_x[j];
        }
        l_w[i] = wi;
    }

    // Write results back to global memory
    // Write A back
    store_A: for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            A[i][j] = l_A[i][j];
        }
    }

    // Write x and w back
    store_xw: for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        x[i] = l_x[i];
        w[i] = l_w[i];
    }
}

} // extern "C"

#include "gesummv.h"

extern "C" {

void kernel_gesummv(
        double alpha,
        double beta,
        double A[N + 0][N + 0],
        double B[N + 0][N + 0],
        double tmp[N + 0],
        double x[N + 0],
        double y[N + 0])
{
#pragma HLS INTERFACE m_axi port=A   offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=B   offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=tmp offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=x   offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=y   offset=slave bundle=gmem4
#pragma HLS INTERFACE s_axilite port=alpha  bundle=control
#pragma HLS INTERFACE s_axilite port=beta   bundle=control
#pragma HLS INTERFACE s_axilite port=A      bundle=control
#pragma HLS INTERFACE s_axilite port=B      bundle=control
#pragma HLS INTERFACE s_axilite port=tmp    bundle=control
#pragma HLS INTERFACE s_axilite port=x      bundle=control
#pragma HLS INTERFACE s_axilite port=y      bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

    // Local buffers to avoid repeated global memory reads
    double x_local[N];
#pragma HLS ARRAY_PARTITION variable=x_local cyclic factor=4 dim=1

    double A_row[N];
#pragma HLS ARRAY_PARTITION variable=A_row cyclic factor=4 dim=1

    double B_row[N];
#pragma HLS ARRAY_PARTITION variable=B_row cyclic factor=4 dim=1

    // Load x into local buffer once
    load_x: for (int k = 0; k < n; k++) {
#pragma HLS PIPELINE II=1
        x_local[k] = x[k];
    }

    int i, j;

    for (i = 0; i < n; i++) {
        // Load row i of A and B into local buffers
        load_A_row: for (int k = 0; k < n; k++) {
#pragma HLS PIPELINE II=1
            A_row[k] = A[i][k];
            B_row[k] = B[i][k];
        }

        double tmp_i = 0.0;
        double y_i   = 0.0;

        // Inner compute loop — pipeline with local arrays for conflict-free access
        compute: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=4
            tmp_i += A_row[j] * x_local[j];
            y_i   += B_row[j] * x_local[j];
        }

        tmp[i] = tmp_i;
        y[i]   = alpha * tmp_i + beta * y_i;
    }
}

} // extern "C"

#include "gramschmidt.h"

extern "C" {

void kernel_gramschmidt(
    double A[M + 0][N + 0],
    double R[N + 0][N + 0],
    double Q[M + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=R offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=Q offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=R bundle=control
#pragma HLS INTERFACE s_axilite port=Q bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local arrays to avoid repeated global memory accesses
    double A_local[M][N];
    double R_local[N][N];
    double Q_local[M][N];

#pragma HLS ARRAY_PARTITION variable=A_local cyclic factor=4 dim=2
#pragma HLS ARRAY_PARTITION variable=Q_local cyclic factor=4 dim=2
#pragma HLS ARRAY_PARTITION variable=R_local cyclic factor=4 dim=2

    // Load A from global memory
    load_A_row:
    for (int i = 0; i < M; i++) {
#pragma HLS PIPELINE II=1
        load_A_col:
        for (int j = 0; j < N; j++) {
            A_local[i][j] = A[i][j];
        }
    }

    const int m = M;
    const int n = N;

    int i, j, k;
    double nrm;

    for (k = 0; k < n; k++) {
        nrm = 0.0;

        // Compute norm
        nrm_loop:
        for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
            nrm += A_local[i][k] * A_local[i][k];
        }

        R_local[k][k] = sqrt(nrm);

        // Compute Q column k
        q_loop:
        for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
            Q_local[i][k] = A_local[i][k] / R_local[k][k];
        }

        // Update R and A for remaining columns
        j_loop:
        for (j = k + 1; j < n; j++) {
            R_local[k][j] = 0.0;

            // Compute R[k][j]
            r_loop:
            for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
                R_local[k][j] += Q_local[i][k] * A_local[i][j];
            }

            // Update A column j
            a_update_loop:
            for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
                A_local[i][j] = A_local[i][j] - Q_local[i][k] * R_local[k][j];
            }
        }
    }

    // Write Q to global memory
    store_Q_row:
    for (int i = 0; i < M; i++) {
#pragma HLS PIPELINE II=1
        store_Q_col:
        for (int j = 0; j < N; j++) {
            Q[i][j] = Q_local[i][j];
        }
    }

    // Write R to global memory
    store_R_row:
    for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        store_R_col:
        for (int j = 0; j < N; j++) {
            R[i][j] = R_local[i][j];
        }
    }

    // Write A back to global memory (modified in-place)
    store_A_row:
    for (int i = 0; i < M; i++) {
#pragma HLS PIPELINE II=1
        store_A_col:
        for (int j = 0; j < N; j++) {
            A[i][j] = A_local[i][j];
        }
    }
}

} // extern "C"

#include "jacobi-1d.h"

extern "C" {

void kernel_jacobi_1d(
    double A[N + 0],
    double B[N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem1
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;
    const int tsteps = TSTEPS;

    // Local buffers to avoid repeated global memory access
    double lA[N];
    double lB[N];

#pragma HLS ARRAY_PARTITION variable=lA cyclic factor=4 dim=1
#pragma HLS ARRAY_PARTITION variable=lB cyclic factor=4 dim=1

    // Load A into local buffer
    load_A: for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        lA[i] = A[i];
    }

    // Load B into local buffer
    load_B: for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        lB[i] = B[i];
    }

    int t, i;

    for (t = 0; t < tsteps; t++)
    {
        // B[i] = 0.33333 * (A[i-1] + A[i] + A[i+1])
        update_B: for (i = 1; i < n - 1; i++) {
#pragma HLS PIPELINE II=1
            lB[i] = 0.33333 * (lA[i-1] + lA[i] + lA[i + 1]);
        }

        // A[i] = 0.33333 * (B[i-1] + B[i] + B[i+1])
        update_A: for (i = 1; i < n - 1; i++) {
#pragma HLS PIPELINE II=1
            lA[i] = 0.33333 * (lB[i-1] + lB[i] + lB[i + 1]);
        }
    }

    // Write back A
    store_A: for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        A[i] = lA[i];
    }

    // Write back B
    store_B: for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        B[i] = lB[i];
    }
}

} // extern "C"

#include "jacobi-2d.h"

extern "C" {

void kernel_jacobi_2d(
                double A[N + 0][N + 0],
                double B[N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem1
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;
    const int tsteps = TSTEPS;

    // Local ping-pong buffers to avoid repeated global memory access
    static double lA[N][N];
    static double lB[N][N];

#pragma HLS ARRAY_PARTITION variable=lA cyclic factor=4 dim=2
#pragma HLS ARRAY_PARTITION variable=lB cyclic factor=4 dim=2

    // Load A into local buffer
    load_A:
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            lA[i][j] = A[i][j];
        }
    }

    int t, i, j;

    for (t = 0; t < tsteps; t++) {

        // B[i][j] = 0.2 * (A[i][j] + A[i][j-1] + A[i][1+j] + A[1+i][j] + A[i-1][j])
        update_B:
        for (i = 1; i < n - 1; i++) {
            for (j = 1; j < n - 1; j++) {
#pragma HLS PIPELINE II=1
                lB[i][j] = 0.2 * (lA[i][j] + lA[i][j-1] + lA[i][1+j] + lA[1+i][j] + lA[i-1][j]);
            }
        }

        // A[i][j] = 0.2 * (B[i][j] + B[i][j-1] + B[i][1+j] + B[1+i][j] + B[i-1][j])
        update_A:
        for (i = 1; i < n - 1; i++) {
            for (j = 1; j < n - 1; j++) {
#pragma HLS PIPELINE II=1
                lA[i][j] = 0.2 * (lB[i][j] + lB[i][j-1] + lB[i][1+j] + lB[1+i][j] + lB[i-1][j]);
            }
        }
    }

    // Write back lA to global A
    store_A:
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            A[i][j] = lA[i][j];
        }
    }

    // Write back lB to global B
    store_B:
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            B[i][j] = lB[i][j];
        }
    }
}

