#include "lu.h"

extern "C" {

void kernel_lu(
    double A[N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local copy to enable parallel access via array partitioning
    double localA[N][N];
#pragma HLS ARRAY_PARTITION variable=localA cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=localA cyclic factor=8 dim=1

    // Load A into local buffer
    load_i: for (int i = 0; i < N; i++) {
        load_j: for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            localA[i][j] = A[i][j];
        }
    }

    const int n = N;
    int i, j, k;

    for (i = 0; i < n; i++) {
        // First j-loop: j < i
        for (j = 0; j < i; j++) {
            // Reduction over k: independent iterations
            for (k = 0; k < j; k++) {
#pragma HLS PIPELINE II=1
#pragma HLS DEPENDENCE variable=localA inter false
                localA[i][j] -= localA[i][k] * localA[k][j];
            }
            localA[i][j] /= localA[j][j];
        }
        // Second j-loop: j >= i
        for (j = i; j < n; j++) {
            // Reduction over k: independent iterations
            for (k = 0; k < i; k++) {
#pragma HLS PIPELINE II=1
#pragma HLS DEPENDENCE variable=localA inter false
                localA[i][j] -= localA[i][k] * localA[k][j];
            }
        }
    }

    // Store local buffer back to A
    store_i: for (int i = 0; i < N; i++) {
        store_j: for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            A[i][j] = localA[i][j];
        }
    }
}

} // extern "C"

#include "ludcmp.h"

extern "C" {

void kernel_ludcmp(
		   double A[ N + 0][N + 0],
		   double b[ N + 0],
		   double x[ N + 0],
		   double y[ N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=b offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=x offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=y offset=slave bundle=gmem3
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=b bundle=control
#pragma HLS INTERFACE s_axilite port=x bundle=control
#pragma HLS INTERFACE s_axilite port=y bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local copies of arrays for efficient on-chip access
    double lA[N][N];
    double lb[N];
    double lx[N];
    double ly[N];

#pragma HLS ARRAY_PARTITION variable=lA cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=lb cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=lx cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=ly cyclic factor=8 dim=1

    const int n = N;
    int i, j, k;
    double w;

    // Load A from global memory
    load_A_outer: for (i = 0; i < n; i++) {
        load_A_inner: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            lA[i][j] = A[i][j];
        }
    }

    // Load b from global memory
    load_b: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        lb[i] = b[i];
    }

    // Load y from global memory
    load_y: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        ly[i] = y[i];
    }

    // LU factorization
    lu_outer: for (i = 0; i < n; i++) {
        // Lower triangular part
        lu_lower: for (j = 0; j < i; j++) {
            w = lA[i][j];
            lu_lower_k: for (k = 0; k < j; k++) {
#pragma HLS PIPELINE II=1
                w -= lA[i][k] * lA[k][j];
            }
            lA[i][j] = w / lA[j][j];
        }
        // Upper triangular part
        lu_upper: for (j = i; j < n; j++) {
            w = lA[i][j];
            lu_upper_k: for (k = 0; k < i; k++) {
#pragma HLS PIPELINE II=1
                w -= lA[i][k] * lA[k][j];
            }
            lA[i][j] = w;
        }
    }

    // Forward substitution: solve L*y = b
    fwd_outer: for (i = 0; i < n; i++) {
        w = lb[i];
        fwd_inner: for (j = 0; j < i; j++) {
#pragma HLS PIPELINE II=1
            w -= lA[i][j] * ly[j];
        }
        ly[i] = w;
    }

    // Backward substitution: solve U*x = y
    bwd_outer: for (i = n-1; i >= 0; i--) {
        w = ly[i];
        bwd_inner: for (j = i+1; j < n; j++) {
#pragma HLS PIPELINE II=1
            w -= lA[i][j] * lx[j];
        }
        lx[i] = w / lA[i][i];
    }

    // Write lA back to global memory
    store_A_outer: for (i = 0; i < n; i++) {
        store_A_inner: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            A[i][j] = lA[i][j];
        }
    }

    // Write lb back to global memory
    store_b: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        b[i] = lb[i];
    }

    // Write lx back to global memory
    store_x: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        x[i] = lx[i];
    }

    // Write ly back to global memory
    store_y: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        y[i] = ly[i];
    }
}

} // extern "C"

#include "mvt.h"

extern "C" {

void kernel_mvt(
        double x1[ N + 0],
        double x2[ N + 0],
        double y_1[ N + 0],
        double y_2[ N + 0],
        double A[ N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=x1  offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=x2  offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=y_1 offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=y_2 offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=A   offset=slave bundle=gmem

#pragma HLS INTERFACE s_axilite port=x1      bundle=control
#pragma HLS INTERFACE s_axilite port=x2      bundle=control
#pragma HLS INTERFACE s_axilite port=y_1     bundle=control
#pragma HLS INTERFACE s_axilite port=y_2     bundle=control
#pragma HLS INTERFACE s_axilite port=A       bundle=control
#pragma HLS INTERFACE s_axilite port=return  bundle=control

    const int n = N;

    // Local buffers for y_1, y_2, and rows of A to enable pipelining
    double local_y1[N];
    double local_y2[N];
    double local_A[N];

#pragma HLS ARRAY_PARTITION variable=local_y1 cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=local_y2 cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=local_A  cyclic factor=8 dim=1

    // Load y_1 into local buffer
    load_y1: for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
        local_y1[j] = y_1[j];
    }

    // Load y_2 into local buffer
    load_y2: for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
        local_y2[j] = y_2[j];
    }

    int i, j;

    // First loop: x1[i] += A[i][j] * y_1[j]
    loop1_outer: for (i = 0; i < n; i++) {
        // Load row i of A into local buffer
        load_A_row: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            local_A[j] = A[i][j];
        }

        double acc1 = x1[i];
        loop1_inner: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
            acc1 += local_A[j] * local_y1[j];
        }
        x1[i] = acc1;
    }

    // Second loop: x2[i] += A[j][i] * y_2[j]
    loop2_outer: for (i = 0; i < n; i++) {
        // Load column i of A into local buffer (A[j][i] for j=0..n-1)
        load_A_col: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            local_A[j] = A[j][i];
        }

        double acc2 = x2[i];
        loop2_inner: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
            acc2 += local_A[j] * local_y2[j];
        }
        x2[i] = acc2;
    }

}

} // extern "C"

#include "nussinov.h"

extern "C" {

void kernel_nussinov( char seq[ N + 0],
                       int table[ N + 0][N + 0])
{
    #pragma HLS INTERFACE m_axi port=seq    offset=slave bundle=gmem0
    #pragma HLS INTERFACE m_axi port=table  offset=slave bundle=gmem1
    #pragma HLS INTERFACE s_axilite port=seq    bundle=control
    #pragma HLS INTERFACE s_axilite port=table  bundle=control
    #pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

    // Local copies for fast on-chip access
    char  l_seq[N];
    int   l_table[N][N];

    #pragma HLS ARRAY_PARTITION variable=l_seq   complete dim=1
    #pragma HLS ARRAY_PARTITION variable=l_table cyclic  factor=8 dim=1
    #pragma HLS ARRAY_PARTITION variable=l_table cyclic  factor=8 dim=2

    // Load seq from global memory
    load_seq: for (int idx = 0; idx < n; idx++) {
        #pragma HLS PIPELINE II=1
        l_seq[idx] = seq[idx];
    }

    // Load table from global memory (row by row)
    load_table: for (int ii = 0; ii < n; ii++) {
        for (int jj = 0; jj < n; jj++) {
            #pragma HLS PIPELINE II=1
            l_table[ii][jj] = table[ii][jj];
        }
    }

    int i, j, k;

    for (i = n-1; i >= 0; i--) {
        for (j = i+1; j < n; j++) {

            if (j-1 >= 0)
                l_table[i][j] = ((l_table[i][j] >= l_table[i][j-1]) ? l_table[i][j] : l_table[i][j-1]);
            if (i+1 < n)
                l_table[i][j] = ((l_table[i][j] >= l_table[i+1][j]) ? l_table[i][j] : l_table[i+1][j]);

            if (j-1 >= 0 && i+1 < n) {
                if (i < j-1)
                    l_table[i][j] = ((l_table[i][j] >= l_table[i+1][j-1] + (((l_seq[i]) + (l_seq[j])) == 3 ? 1 : 0)) ? l_table[i][j] : l_table[i+1][j-1] + (((l_seq[i]) + (l_seq[j])) == 3 ? 1 : 0));
                else
                    l_table[i][j] = ((l_table[i][j] >= l_table[i+1][j-1]) ? l_table[i][j] : l_table[i+1][j-1]);
            }

            int max_val = l_table[i][j];
            for (k = i+1; k < j; k++) {
                #pragma HLS PIPELINE II=1
                int candidate = l_table[i][k] + l_table[k+1][j];
                max_val = (max_val >= candidate) ? max_val : candidate;
            }
            l_table[i][j] = max_val;
        }
    }

    // Store table back to global memory
    store_table: for (int ii = 0; ii < n; ii++) {
        for (int jj = 0; jj < n; jj++) {
            #pragma HLS PIPELINE II=1
            table[ii][jj] = l_table[ii][jj];
        }
    }
}

} // extern "C"

#include "symm.h"

extern "C" {

void kernel_symm(
        double alpha,
        double beta,
        double C[M][N],
        double A[M][M],
        double B[M][N])
{
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=alpha  bundle=control
#pragma HLS INTERFACE s_axilite port=beta   bundle=control
#pragma HLS INTERFACE s_axilite port=C      bundle=control
#pragma HLS INTERFACE s_axilite port=A      bundle=control
#pragma HLS INTERFACE s_axilite port=B      bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local copies for fast on-chip access
    double lC[M][N];
    double lA[M][M];
    double lB[M][N];

#pragma HLS ARRAY_PARTITION variable=lC cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=lA cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=lB cyclic factor=8 dim=2

    // Load C from global memory
    load_C:
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            lC[i][j] = C[i][j];
        }
    }

    // Load A from global memory
    load_A:
    for (int i = 0; i < M; i++) {
        for (int k = 0; k < M; k++) {
#pragma HLS PIPELINE II=1
            lA[i][k] = A[i][k];
        }
    }

    // Load B from global memory
    load_B:
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            lB[i][j] = B[i][j];
        }
    }

    // Compute kernel
    const int m = M;
    const int n = N;

    int i, j, k;
    double temp2;

    compute_i:
    for (i = 0; i < m; i++) {
        compute_j:
        for (j = 0; j < n; j++) {
            temp2 = 0;
            compute_k:
            for (k = 0; k < i; k++) {
#pragma HLS PIPELINE II=1
                lC[k][j] += alpha * lB[i][j] * lA[i][k];
                temp2 += lB[k][j] * lA[i][k];
            }
            lC[i][j] = beta * lC[i][j] + alpha * lB[i][j] * lA[i][i] + alpha * temp2;
        }
    }

    // Store C back to global memory
    store_C:
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            C[i][j] = lC[i][j];
        }
    }
}

} // extern "C"

#include "syr2k.h"

extern "C" {

void kernel_syr2k(
          double alpha,
          double beta,
          double C[N][N],
          double A[N][M],
          double B[N][M])
{
    #pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem0
    #pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
    #pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
    #pragma HLS INTERFACE s_axilite port=alpha bundle=control
    #pragma HLS INTERFACE s_axilite port=beta  bundle=control
    #pragma HLS INTERFACE s_axilite port=C     bundle=control
    #pragma HLS INTERFACE s_axilite port=A     bundle=control
    #pragma HLS INTERFACE s_axilite port=B     bundle=control
    #pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local buffers to stage data for reuse across the k-loop
    double localC[N][N];
    double localA[N][M];
    double localB[N][M];

    #pragma HLS ARRAY_PARTITION variable=localC cyclic factor=8 dim=2
    #pragma HLS ARRAY_PARTITION variable=localA cyclic factor=8 dim=2
    #pragma HLS ARRAY_PARTITION variable=localB cyclic factor=8 dim=2

    const int n = N;
    const int m = M;

    // Load C into local buffer
    load_C_i: for (int i = 0; i < n; i++) {
        load_C_j: for (int j = 0; j < n; j++) {
            #pragma HLS PIPELINE II=1
            localC[i][j] = C[i][j];
        }
    }

    // Load A into local buffer
    load_A_i: for (int i = 0; i < n; i++) {
        load_A_k: for (int k = 0; k < m; k++) {
            #pragma HLS PIPELINE II=1
            localA[i][k] = A[i][k];
        }
    }

    // Load B into local buffer
    load_B_i: for (int i = 0; i < n; i++) {
        load_B_k: for (int k = 0; k < m; k++) {
            #pragma HLS PIPELINE II=1
            localB[i][k] = B[i][k];
        }
    }

    // Compute: scale lower triangle of C by beta
    scale_i: for (int i = 0; i < n; i++) {
        scale_j: for (int j = 0; j <= i; j++) {
            #pragma HLS PIPELINE II=1
            localC[i][j] *= beta;
        }
    }

    // Compute: update lower triangle of C
    compute_i: for (int i = 0; i < n; i++) {
        compute_k: for (int k = 0; k < m; k++) {
            compute_j: for (int j = 0; j <= i; j++) {
                #pragma HLS PIPELINE II=1
                localC[i][j] += localA[j][k] * alpha * localB[i][k]
                              +  localB[j][k] * alpha * localA[i][k];
            }
        }
    }

    // Store result back to global memory (lower triangle only)
    store_i: for (int i = 0; i < n; i++) {
        store_j: for (int j = 0; j < n; j++) {
            #pragma HLS PIPELINE II=1
            C[i][j] = localC[i][j];
        }
    }
}

} // extern "C"

#include "syrk.h"

void kernel_syrk(
    double alpha,
    double beta,
    double C[N + 0][N + 0],
    double A[N + 0][M + 0])
{
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta  bundle=control
#pragma HLS INTERFACE s_axilite port=C     bundle=control
#pragma HLS INTERFACE s_axilite port=A     bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local copies to enable partitioning and fast local access
    double localC[N][N];
    double localA[N][M];

#pragma HLS ARRAY_PARTITION variable=localC cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=localA cyclic factor=8 dim=2

    // Load A into local buffer
    load_A_outer: for (int i = 0; i < N; i++) {
        load_A_inner: for (int k = 0; k < M; k++) {
#pragma HLS PIPELINE II=1
            localA[i][k] = A[i][k];
        }
    }

    // Load lower triangle of C into local buffer
    load_C_outer: for (int i = 0; i < N; i++) {
        load_C_inner: for (int j = 0; j <= i; j++) {
#pragma HLS PIPELINE II=1
            localC[i][j] = C[i][j];
        }
    }

    const int n = N;
    const int m = M;

    int i, j, k;

    // Scale lower triangle of C by beta
    scale_i: for (i = 0; i < n; i++) {
        scale_j: for (j = 0; j <= i; j++) {
#pragma HLS PIPELINE II=1
            localC[i][j] *= beta;
        }
    }

    // Symmetric rank-k update: C += alpha * A * A^T (lower triangle)
    update_i: for (i = 0; i < n; i++) {
        update_k: for (k = 0; k < m; k++) {
#pragma HLS PIPELINE II=1
            double aik = localA[i][k];
            update_j: for (j = 0; j <= i; j++) {
#pragma HLS UNROLL factor=8
                localC[i][j] += alpha * aik * localA[j][k];
            }
        }
    }

    // Store lower triangle of C back to global memory
    store_C_outer: for (int i = 0; i < N; i++) {
        store_C_inner: for (int j = 0; j <= i; j++) {
#pragma HLS PIPELINE II=1
            C[i][j] = localC[i][j];
        }
    }
}

#include "trisolv.h"

extern "C" {

void kernel_trisolv(
        double L[N + 0][N + 0],
        double x[N + 0],
        double b[N + 0])
{
#pragma HLS INTERFACE m_axi port=L offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=x offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=b offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=L bundle=control
#pragma HLS INTERFACE s_axilite port=x bundle=control
#pragma HLS INTERFACE s_axilite port=b bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local buffers for x and b to allow parallel access
    double x_local[N];
    double b_local[N];
    double L_row[N];

#pragma HLS ARRAY_PARTITION variable=x_local cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=L_row cyclic factor=8 dim=1

    const int n = N;

    // Load b into local buffer
    load_b: for (int k = 0; k < n; k++) {
#pragma HLS PIPELINE II=1
        b_local[k] = b[k];
    }

    int i, j;

    for (i = 0; i < n; i++) {
        // Load L row i into local buffer
        load_L_row: for (int k = 0; k < n; k++) {
#pragma HLS PIPELINE II=1
            L_row[k] = L[i][k];
        }

        double xi = b_local[i];

        // Inner loop: accumulate sum L[i][j] * x[j] for j < i
        inner_loop: for (j = 0; j < i; j++) {
#pragma HLS PIPELINE II=1
            xi -= L_row[j] * x_local[j];
        }

        xi = xi / L_row[i];
        x_local[i] = xi;
    }

    // Write x back
    store_x: for (int k = 0; k < n; k++) {
#pragma HLS PIPELINE II=1
        x[k] = x_local[k];
    }
}

} // extern "C"

#include "trmm.h"

extern "C" {

void kernel_trmm(
        double alpha,
        double A[M + 0][M + 0],
        double B[M + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem1
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local copies for fast on-chip access
    double A_local[M][M];
    double B_local[M][N];

#pragma HLS ARRAY_PARTITION variable=A_local cyclic factor=4 dim=1
#pragma HLS ARRAY_PARTITION variable=A_local cyclic factor=4 dim=2
#pragma HLS ARRAY_PARTITION variable=B_local cyclic factor=4 dim=1
#pragma HLS ARRAY_PARTITION variable=B_local cyclic factor=4 dim=2

    // Load A into local buffer
    load_A_outer: for (int i = 0; i < M; i++) {
        load_A_inner: for (int j = 0; j < M; j++) {
#pragma HLS PIPELINE II=1
            A_local[i][j] = A[i][j];
        }
    }

    // Load B into local buffer
    load_B_outer: for (int i = 0; i < M; i++) {
        load_B_inner: for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            B_local[i][j] = B[i][j];
        }
    }

    // Compute kernel
    const int m = M;
    const int n = N;

    int i, j, k;
    for (i = 0; i < m; i++) {
        for (j = 0; j < n; j++) {
            double bval = B_local[i][j];
            compute_k: for (k = i + 1; k < m; k++) {
#pragma HLS PIPELINE II=1
                bval += A_local[k][i] * B_local[k][j];
            }
            B_local[i][j] = alpha * bval;
        }
    }

    // Store B back to global memory
    store_B_outer: for (int i = 0; i < M; i++) {
        store_B_inner: for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            B[i][j] = B_local[i][j];
        }
    }
}

} // extern "C"
